class Pila {
  #items = [];
  #maxSize;

  constructor(maxSize = Infinity) {
    this.#maxSize = maxSize;
  }

  push(item) {
    if (this.#items.length >= this.#maxSize) {
      throw new Error(`Pila llena (máx: ${this.#maxSize})`);
    }
    this.#items.push(item);
    return this;
  }

  pop() {
    if (this.#estaVacia()) throw new Error('Pila vacía');
    return this.#items.pop();
  }

  peek() {
    if (this.#estaVacia()) return undefined;
    return this.#items[this.#items.length - 1];
  }

  #estaVacia() { return this.#items.length === 0; }

  get size() { return this.#items.length; }
  get isEmpty() { return this.#estaVacia(); }
}

const p = new Pila(3);
p.push(1).push(2).push(3);
console.log(p.peek()); // 3
console.log(p.pop());  // 3
console.log(p.size);   // 2

class EventEmitter {
  #listeners = new Map();

  on(evento, callback) {
    if (!this.#listeners.has(evento)) {
      this.#listeners.set(evento, []);
    }
    this.#listeners.get(evento).push(callback);
    return this;
  }

  emit(evento, ...args) {
    const callbacks = this.#listeners.get(evento) ?? [];
    callbacks.forEach(cb => cb(...args));
    return this;
  }

  off(evento, callback) {
    const cbs = this.#listeners.get(evento) ?? [];
    this.#listeners.set(evento, cbs.filter(cb => cb !== callback));
    return this;
  }
}

const emitter = new EventEmitter();
const handler = (msg) => console.log(`Recibido: ${msg}`);

emitter.on('mensaje', handler);
emitter.emit('mensaje', 'Hola'); // 'Recibido: Hola'
emitter.off('mensaje', handler);
emitter.emit('mensaje', 'Adios'); // (silencio)

